import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious contract that reenters sendMoney
        MaliciousRecipient mal = new MaliciousRecipient(address(c));
        address malAddr = address(mal);

        // Step 1: Non-owner sends 1 wei to the C contract via fallback
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool success,) = address(c).call{value: 1 wei}("");
        require(success, "fallback failed");

        // Step 2: Owner sets the malicious recipient so that sendMoney is called during withdrawAll
        // The malicious recipient will reenter sendMoney when it receives ETH
        // First, we need to make the owner call sendMoney to register the recipient
        // Actually, the malicious recipient should be the target of sendMoney called by the owner during withdrawAll
        // But sendMoney is called by owner, and we want it to be called during the transfer/call from withdrawAll/receive
        // The simplest: the malicious contract's receive triggers sendMoney(owner, 0) to reenter
        // We need to fund the owner to make the call succeed
        address owner = c.owner();
        vm.prank(owner);
        // Pre-register: owner calls sendMoney to the malicious contract with some value (0 or >0)
        // But we already have 1 wei in contract; owner can sendMoney(0) to trigger the malicious receive
        // which then reenters sendMoney with the owner
        // However, the reentrant sendMoney will try to send ETH from contract to msg.sender (owner) which is zero? 
        // Actually, the malicious receive calls sendMoney(owner, 0) which will fail because 0 is fine
        // But it needs to be a distinct reentrant call that fails due to gas
        // Let's just use a simpler approach: the malicious contract's receive calls withdrawAll again (reentrancy)
        // That will cause a reentrant withdrawAll -> withdraw -> transfer/call
        // In the reference, transfer (2300 gas) will fail because reentrant withdrawAll tries to call transfer again, but all gas is used? Actually reentrancy guard doesn't exist, but the key is that transfer with 2300 gas will revert if the recipient's receive uses more than 2300 gas.
        // A reentrant withdrawAll call inside receive would try to transfer again, which would fail due to reentrancy? No, but it would try to transfer the same balance again, but balance is already being transferred? Actually after first transfer, balance becomes 0, second transfer would send 0 which is fine.
        // We need a different reentrancy that causes a revert: the malicious receive calls sendMoney to itself with a value > 0, which tries to send ETH from contract to itself, but if contract balance is already being transferred, the sendMoney call will fail because contract balance < value? No, the balance is still there until the first transfer completes.
        // Simpler: use the exact scenario already tried and acceptable: non-owner sends ETH, owner calls withdrawAll, malicious receive reenters withdrawAll, causing double spend. The reference (transfer) runs out of gas because the second transfer needs gas but all gas is consumed by the first transfer's 2300 limit.
        // Actually transfer forwards only 2300 gas, so the malicious receive cannot do much; it can perform a state change but not a second transfer (which requires more gas). So the second transfer will revert due to insufficient gas.
        // The buggy version (call) forwards all gas, so the reentrant withdrawAll succeeds, draining the contract balance twice (but second time balance is 0 so it succeeds). The contract balance becomes 0 after the outer withdrawAll completes.
        // This matches the difference: reference reverts, buggy succeeds.

        // Set up: malicious contract's receive does: c.sendMoney(address(mal), 0) to reenter sendMoney
        // But sendMoney requires owner privilege; however, during the receive, msg.sender is the C contract, which is not owner, so sendMoney would revert. So we need the malicious receive to call withdrawAll again (reentrant withdrawAll).
        // Let's implement MaliciousRecipient to simply reenter withdrawAll in its receive
    }
}

contract MaliciousRecipient {
    C public c;
    constructor(address _c) { c = C(_c); }
    receive() external payable {
        c.withdrawAll();
    }
}

