        Reverter reverter = new Reverter();

        // Fund the contract with 1 ether via fallback
        vm.deal(address(this), 1 ether);
        (bool success,) = address(c).call{value: 1 ether}("");
        assertTrue(success);

        // Call sendMoney to the reverter with 0.5 ether
        bool ok;
        try c.sendMoney(address(reverter), 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference (.call) succeeds, bug (.transfer) reverts
